    65→public(package) fun util_rate<MarketType>(self: &Reserve<MarketType>): Decimal {
    66→    if (self.debt.is_zero()) {
    67→        return float::from_quotient(0, 1)
    68→    };
    69→
    70→    let denominator = self.cash_plus_borrows_minus_reserves();
    71→    self.debt.div(denominator)
    72→}
    73→
    74→public(package) fun cash_plus_borrows_minus_reserves<MarketType,>(self: &Reserve<MarketType>): Decimal {
    75→    self.debt.add_u64(self.cash).sub(self.cash_reserve)
    76→}
