   223→/// Returns a hot potato ReserveFlashLoan along with the coin. Technically there is no need to but adding this extra
   224→/// type for reserve module to know all lend flash loans are properly paid. Fees are extra.
   225→public(package) fun borrow_flash_loan<MarketType, CoinType>(
   226→    self: &mut Reserve<MarketType>,
   227→    amount: u64,
   228→): (Balance<CoinType>, ReserveFlashLoan<MarketType, CoinType>) {
   229→    // allow flash loan to borrow reserves
   230→    assert!(amount < self.cash, error::reserve_flash_loan_more_than_cash());
   231→    (self.flash_loan_withdraw(amount), ReserveFlashLoan { amount })
   232→}
   233→
   234→public(package) fun repay_flash_loan<MarketType, CoinType>(
   235→    self: &mut Reserve<MarketType>,
   236→    
   237→    loan: ReserveFlashLoan<MarketType, CoinType>,
   238→    coin: Coin<CoinType>,
   239→
   240→    fee: Coin<CoinType>,
   241→) {
   242→    let reserve_token_balance: &mut ReserveBalance<MarketType, CoinType> = dynamic_field::borrow_mut(&mut self.id, ReserveBalanceKey{});
   243→
   244→    let ReserveFlashLoan { amount } = loan;
   245→    assert!(coin.value() == amount, error::reserve_flash_loan_not_paid_enough());
   246→    reserve_token_balance.underlying_balance.join(coin.into_balance());
   247→
   248→    // fee is extra cash for the cash reserve
   249→    if (fee.value() == 0) {
   250→        fee.destroy_zero();
   251→        return
   252→    };
   253→    self.increase_reserve_only<MarketType, CoinType>(fee);
   254→}
   255→
   256→/// Take cash_reserve of the protocol from the reserve
   257→public(package) fun take_revenue<MarketType, CoinType>(self: &mut Reserve<MarketType>, amount: u64): Balance<CoinType> {
   258→    let amount_decimal = float::from(amount);
   259→    assert!(self.cash_reserve.ge(amount_decimal), error::take_too_much_revenue());
   260→
   261→    self.cash_reserve = self.cash_reserve.sub(amount_decimal);
   262→    self.withdraw_underlying(amount)
   263→}
   264→
   265→fun increase_ctoken_supply<MarketType, CoinType>(
   266→    self: &mut Reserve<MarketType>,
   267→    amount: u64,
   268→): Balance<CToken<MarketType, CoinType>> {
   269→    let reserve_token_balance: &mut ReserveBalance<MarketType, CoinType> = dynamic_field::borrow_mut(&mut self.id, ReserveBalanceKey{});
   270→
   271→    self.total_supply = self.total_supply + amount;
   272→    reserve_token_balance.ctoken_supply.increase_supply(amount)
   273→}
   274→
   275→fun decrease_ctoken_supply<MarketType, CoinType>(
   276→    self: &mut Reserve<MarketType>,
   277→    balance: Balance<CToken<MarketType, CoinType>>,
   278→){
   279→    let reserve_token_balance: &mut ReserveBalance<MarketType, CoinType> = dynamic_field::borrow_mut(&mut self.id, ReserveBalanceKey{});
   280→
   281→    self.total_supply = self.total_supply - balance.value();
   282→    reserve_token_balance.ctoken_supply.decrease_supply(balance);
   283→}
   284→
   285→fun increase_reserve_only<MarketType, CoinType>(
   286→    self: &mut Reserve<MarketType>,
   287→    coin: Coin<CoinType>,
   288→) {
   289→    let reserve_token_balance: &mut ReserveBalance<MarketType, CoinType> = dynamic_field::borrow_mut(&mut self.id, ReserveBalanceKey{});
   290→
   291→    self.cash_reserve = self.cash_reserve.add(float::from(coin.value()));
   292→    self.cash = self.cash + coin.value();
   293→    reserve_token_balance.underlying_balance.join(coin.into_balance());
   294→}
   295→
   296→fun deposit_underlying<MarketType, CoinType>(
   297→    self: &mut Reserve<MarketType>,
   298→    coin: Coin<CoinType>,
   299→) {
   300→    let reserve_token_balance: &mut ReserveBalance<MarketType, CoinType> = dynamic_field::borrow_mut(&mut self.id, ReserveBalanceKey{});
   301→
   302→    self.cash = self.cash + coin.value();
   303→    reserve_token_balance.underlying_balance.join(coin.into_balance());
   304→}
   305→
   306→fun withdraw_underlying<MarketType, CoinType>(
   307→    self: &mut Reserve<MarketType>,
   308→    amount: u64,
   309→): Balance<CoinType> {
   310→    let reserve_token_balance: &mut ReserveBalance<MarketType, CoinType> = dynamic_field::borrow_mut(&mut self.id, ReserveBalanceKey{});
   311→
   312→    self.cash = self.cash - amount;
   313→    assert!(self.cash >= self.cash_reserve.ceil(), error::market_cash_reserve_not_enough());
   314→
   315→    reserve_token_balance.underlying_balance.split(amount)
   316→}
   317→
   318→fun flash_loan_withdraw<MarketType, CoinType>(
   319→    self: &mut Reserve<MarketType>,
   320→    amount: u64,
   321→): Balance<CoinType> {
   322→    let reserve_token_balance: &mut ReserveBalance<MarketType, CoinType> = dynamic_field::borrow_mut(&mut self.id, ReserveBalanceKey{});
   323→    reserve_token_balance.underlying_balance.split(amount)
   324→}
