    45→public fun new_adl_params<MarketType>(
    46→    _: &AdminCap,
    47→    self: &ProtocolApp,
    48→    market: &Market<MarketType>,
    49→
    50→    target_amount: u64,
    51→
    52→    liquidation_factor_base_bps: u64,
    53→    liquidation_factor_hourly_drop_large: u64,
    54→
    55→    liquidation_incentive_base_bps: u64,
    56→    liquidation_incentive_daily_penalty_large: u64,
    57→
    58→    close_factor_bps: u64,
    59→): DeleverageParams {
    60→    assert!(0 < liquidation_factor_base_bps && liquidation_factor_base_bps <= BPS_DENOMINATOR, error::invalid_params_error());
    61→    assert!(0 < close_factor_bps && close_factor_bps <= BPS_DENOMINATOR, error::invalid_params_error());
    62→
    63→    check_market<MarketType>(self, market);
    64→
    65→    let liquidation_factor_base = float::from_quotient(liquidation_factor_base_bps, BPS_DENOMINATOR);
    66→    let liquidation_factor_hourly_drop = float::from_quotient(liquidation_factor_hourly_drop_large, LARGE_DENOMINATOR);
    67→
    68→    let liquidation_incentive_base = float::from_quotient(liquidation_incentive_base_bps, BPS_DENOMINATOR);
    69→    let liquidation_incentive_daily_penalty = float::from_quotient(liquidation_incentive_daily_penalty_large, LARGE_DENOMINATOR);
    70→
    71→    let close_factor = float::from_quotient(close_factor_bps, BPS_DENOMINATOR);
    72→
    73→    new_auto_deleverage_params(
    74→        target_amount, 
    75→        liquidation_factor_base, 
    76→        liquidation_factor_hourly_drop, 
    77→        liquidation_incentive_base, 
    78→        liquidation_incentive_daily_penalty, 
    79→        close_factor
    80→    )
    81→}
